function parseStudentCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('علامات اقتباس غير مكتملة في ملف CSV.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const head=(rows.shift()||[]).map(x=>x.replace(/^\uFEFF/,'').trim());if(head.join(',')!=='id,name,classId')throw Error('الحقول المطلوبة: id,name,classId');if(rows.length>500)throw Error('الحد الأقصى 500 صف في المعاينة.');return rows.map(r=>({id:(r[0]||'').trim(),name:(r[1]||'').trim(),classId:(r[2]||'').trim(),invalid:r.length!==3}))}
function validateImport(rows){const seen=new Set(MODEL.students.map(s=>s.id)),counts={};return rows.map(x=>{let error='';const c=classes().find(c=>c.id===x.classId);if(x.invalid||!/^STU\d{5}$/.test(x.id)||x.name.length<3)error='بيانات ناقصة أو غير صالحة';else if(seen.has(x.id))error='معرّف مكرر';else if(!c)error='صف خارج النطاق';else if(c.enrolled+(counts[c.id]||0)>=c.capacity)error='تجاوز السعة';if(!error){counts[c.id]=(counts[c.id]||0)+1;seen.add(x.id)}return {...x,error}})}

